    /\s+(?:(?:set|make|give|put|use)\s+(?:the\s+)?(?:same\s+)?(?:deadline|due\s+date)\s+(?:to|as|for|on)|(?:set|make)\s+(?:all|each|every|these|them)\s+due\s+(?:to|by|on)?|(?:all|each|every|these|them)\s+(?:are\s+)?due\s+(?:by|on))\s+.+$/i
