  if (listed.length < 2) return input;
  const existing = Array.isArray(input.deadlines) ? input.deadlines.filter((task) => task && typeof task.description === "string") : [];
  const trailingGroupDeadline = visible.some((task) => task.hasTrailingGroupDeadline);
  const dated = existing.filter((task) => task.due_date);
  const sharedDate = trailingGroupDeadline && dated.length > 0 && dated.every((task) => task.due_date === dated[0].due_date) ? { due_date: dated[0].due_date, ...dated[0].due_time ? { due_time: dated[0].due_time } : {} } : {};
